    counts = {}
    for num in nums:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    # Find the minimum value in the counts
    min_val = min(counts.values())

    # Check if the minimum value is greater than or equal to the length of the array
    if min_val >= N:
        return False

    # Check if the maximum value is less than or equal to the length of the array
    max_val = max(counts.values())

    # Check if the difference between the minimum and maximum values is less than or equal to 1
    if abs(min_val - max_val) <= 1:
        return True
    else:
        return False
